export const formatFCFA = (amount) => {
    return amount.toLocaleString('fr-FR') + ' FCFA';
};

export const getProductByCode = (code) => {
    return products.find(p => p.code === code);
};

export const getProductsByCategory = (categorySlug) => {
    return products.filter(p => p.categorySlug === categorySlug || p.parentCategory.toLowerCase().replace(/[\s&]/g, '-').replace(/--+/g, '-') === categorySlug);
};

export const searchProducts = (query) => {
    const q = query.toLowerCase();
    return products.filter(p => p.model.toLowerCase().includes(q) || p.code.includes(q));
};

export const getAllProducts = () => products;

export default products;
